def solve(g, axis):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    out=[r[:] for r in g]
    def wall(r,c): return g[r][c]==8
    seed=[(r,c) for r in range(H) for c in range(W) if g[r][c]==2][0]
    if axis=='h':
        t=seed[0]; cells={seed[1]}
        fwall=lambda t,u: t+1>=H or wall(t+1,u)
    else:
        t=seed[1]; cells={seed[0]}
        fwall=lambda t,u: t+1>=W or wall(u,t+1)
    lim = H if axis=='h' else W
    for t in range(seed[0] if axis=='h' else seed[1], lim):
        for u in cells:
            if axis=='h': out[t][u]=2
            else: out[u][t]=2
        blocked=[u for u in cells if fwall(t,u)]
        if t==lim-1: break
        if not blocked:
            cells={u for u in cells}  # move forward
            continue
        occ=set(cells)
        for u in blocked:
            for d in (1,-1):
                v=u+d
                while 0<=v<(W if axis=='h' else H):
                    occ.add(v)
                    if not fwall(t,v): break
                    v+=d
        for u in occ:
            if axis=='h': out[t][u]=2
            else: out[u][t]=2
        cells={u for u in occ if not fwall(t,u)}
        t+=1
    return out

